    case uninstallTitle = "uninstall.title"
    case uninstallTotalSize = "uninstall.totalSize"
    case uninstallUninstallButton = "uninstall.uninstallButton"
    case uninstallVersion = "uninstall.version"
}

extension LocalizationKey {
    /// The localised string, resolved against the bundled catalog.
    ///
    /// Resolution uses the explicitly selected language bundle rather than
    /// `LocalizedStringKey`, which would consult the main bundle and ignore this
    /// preference. Returning the resolved string allows the UI language to change
    /// immediately without requiring an application restart.
    ///
    /// Missing translations fall back to English, which the catalog records as
    /// the source language.
    public var localized: String {
        Bundle.localizedBundle(for: SiftLanguage.current).localizedString(forKey: rawValue, value: nil, table: "Localizable")
    }

    /// The localised string with positional arguments substituted.
    public func localized(_ arguments: CVarArg...) -> String {
        String(format: localized, arguments: arguments)
    }
}
